const layers=specs.flatMap(([selector,dx,dy])=>[...document.querySelectorAll(selector)].map(el=>({el,dx,dy,x:gsap.quickTo(el,'x',{duration:.65,ease:'power3.out'}),y:gsap.quickTo(el,'y',{duration:.65,ease:'power3.out'})})));
